# =============================================================================================== settings
def cfg(S: dict | None = None, slug: str | None = None) -> dict:
    """Effective `cinematic` settings (module defaults <- global <- episode). Accepts a full settings dict or the section."""
    if S is None:
        S = SET.load(slug)
    sec = S.get("cinematic", S) if isinstance(S, dict) else {}
    out = {**DEFAULTS, **{k: v for k, v in sec.items() if k in DEFAULTS}}
    out["allowed_kinds"] = [k for k in KINDS if k not in set(out.get("disabled_kinds") or [])]
    if not out["pov_shots"]:
        out["allowed_kinds"] = [k for k in out["allowed_kinds"] if k not in ("pov", "spectate")]
    return out


def _read(p: Path, default=None):
    try:
        return json.loads(Path(p).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


def _write(p: Path, data) -> None:
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_name(p.name + ".tmp")
    tmp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    tmp.replace(p)


def _proj(slug: str) -> Path:
    p = PROJECTS / slug
    if not p.exists():
        raise SystemExit(f"project '{slug}' not found in {PROJECTS}")
    return p


def shots_path(slug: str) -> Path:
    return PROJECTS / slug / "broll" / "shots.json"


def load_shots(slug: str) -> dict | None:
    return _read(shots_path(slug))

def overlap_s(a: dict, b: dict) -> float:
    return max(0.0, min(a["end"], b["end"]) - max(a["start"], b["start"]))


def find_replay(slug: str, dirs: list[Path] | None = None, min_overlap_s: float = 10.0,
                window: dict | None = None) -> dict | None:
    """The replay overlapping the project's recording in wall-clock time (largest overlap; Flashback preferred because
    its reader exists). -> replay_window dict + {'overlap_s'} or None."""
    vw = window or video_window(slug)
    cands = []
    for r in list_replays(dirs):
        ov = overlap_s(vw, r)
        if ov >= min_overlap_s:
            cands.append({**r, "overlap_s": round(ov, 2)})
    if not cands:
        return None
    cands.sort(key=lambda r: (r["kind"] == "flashback", r["overlap_s"], r["end"]), reverse=True)
    return cands[0]


# =============================================================================================== sync
def estimate_sync(vw: dict, rw: dict) -> dict:
    """Timestamp sync: offset_s = replay time (s) at video t=0. Negative = the replay started after the recording did."""
    off = vw["start"] - rw["start"]
    ov = overlap_s(vw, rw)
    cover = ov / max(vw["dur"], 1e-6)
    # clocks agree to ~1-3 s when OBS and the game ran on one PC; a low overlap means shots near the ends fall outside
    conf = round(0.35 * min(1.0, cover) + 0.05, 3)
    return {"offset_s": round(off, 3), "method": "timestamps", "confidence": conf,
            "notes": f"video start {datetime.fromtimestamp(vw['start']):%H:%M:%S} ({vw['how']}) vs replay start "
                     f"{datetime.fromtimestamp(rw['start']):%H:%M:%S}; overlap {ov:.0f}s of {vw['dur']:.0f}s video; "
                     "timestamps are only good to a few seconds - refine with motion-xcorr"}


