def plan_shots(slug: str, replay=None, settings: dict | None = None, sync: dict | None = None,
               write: bool = True) -> dict:
    """Choose cinematic shots for an episode. `replay` = Replay-like object, path, or None (auto-find a Flashback replay;
    no replay -> abstract shots without ticks). Returns the shots.json dict (written unless write=False).
    If projects/<slug>/edit.json exists the plan respects its cuts and existing memes/stickers/green screens (timeline =
    output time); otherwise it plans on the raw recording's timeline and splice() resolves conflicts later."""
    S = settings if settings is not None else SET.load(slug)
    C = cfg(S)
    ctx = _Ctx(slug, C)
    rpath, rkind, rw = None, "flashback", None
    notes: list[str] = []
    if isinstance(replay, (str, Path)):
        rw = replay_window(Path(replay))
        rpath, rkind = str(replay), rw["kind"]
        replay = load_replay(replay)
    elif replay is None:
        found = find_replay(slug)
        if found:
            rw, rpath, rkind = found, found["path"], found["kind"]
            try:
                replay = load_replay(found["path"])
            except NotImplementedError as e:
                notes.append(str(e))
                replay = None
        else:
            notes.append("no replay overlaps this recording in time - shots are planned without replay ticks")
    else:
        rpath = str(getattr(replay, "path", ""))
        rkind = "synthetic" if getattr(replay, "synthetic", False) else "flashback"
    if sync is None:
        if rw is not None:
            vw = video_window(slug)
            sync = estimate_sync(vw, rw)
            if C["refine_sync"] and replay is not None and vw.get("file") and Path(vw["file"]).exists():
                sync = refine_sync(vw["file"], replay, sync, C["sync_min_confidence"])
        else:
            sync = {"offset_s": 0.0, "method": "timestamps", "confidence": 0.0, "notes": "no replay: offset unknown"}
    sync = {**sync, "offset_s": float(sync["offset_s"])}
    cands = _candidates(ctx, C, replay, sync) if C["enabled"] else []

    # ---- choose: greedy by priority under gap / rate caps (all on the timeline)
    tl = ctx.timeline_total
    n_max = max(1 if tl > 40 else 0, int(C["max_shots_per_min"] * tl / 60.0 + 0.5))
    per_min = max(1, math.ceil(C["max_shots_per_min"]))
    chosen: list[dict] = []
    skipped: list[dict] = []
    track = replay.player_track() if replay is not None and hasattr(replay, "player_track") else None
    ticks_total = getattr(replay, "total_ticks", None)
    dull = ("aerial_establish", "flyby", "timelapse")
    for c in sorted(cands, key=lambda c: -(c["prio"] + (ctx.dark_frac(c["anchor"], c["anchor"] + 3) * 3
                                                        if c["kind"] in dull else 0))):
        def skip(why):
            skipped.append({"kind": c["kind"], "reason": c["reason"], "why": why})
        if len(chosen) >= n_max:
            skip("shot budget used up")
            continue
        dur = _clamp_dur(c["kind"], C["shot_len_s"])
        placed = _place(ctx, c["anchor"], dur, c["dir"], C, max_shift=c.get("max_shift", 4.0))
        if placed is None:
            skip("no free window (would cover a punchline / counter / death screen / meme / the hook)")
            continue
        t0, d = placed
        if any(not (t0 >= o["out_t"] + o["dur_s"] + C["min_gap_s"] or t0 + d + C["min_gap_s"] <= o["out_t"])
               for o in chosen):
            skip(f"closer than {C['min_gap_s']:g}s to another shot")
            continue
        times = sorted([o["out_t"] for o in chosen] + [t0])
        if any(sum(1 for q in times if 0 <= q - w < 60) > per_min for w in times):
            skip("per-minute cap")
            continue
        vt = ctx.src(t0)
        tick = round((vt + sync["offset_s"]) * 20) if replay is not None else None
        ticks = round(d * 20)
        if tick is not None and ticks_total is not None and (tick < 0 or tick + ticks > ticks_total):
            skip(f"outside the replay (tick {tick} of {ticks_total})")
            continue
        chosen.append({"kind": c["kind"], "moment": c["moment"], "reason": c["reason"], "video_t": vt, "out_t": t0,
                       "dur_s": d, "replay_tick": tick, "ticks": ticks, "src": c["src"], "death_t": c.get("death_t")})
    chosen.sort(key=lambda o: o["out_t"])
    for i in range(1, len(chosen)):                          # variety: never the same kind back to back
        if chosen[i]["kind"] == chosen[i - 1]["kind"]:
            alt = next((k for k in FAMILY.get(chosen[i]["kind"], []) if k in C["allowed_kinds"]
                        and k != chosen[i - 1]["kind"]), None)
            if alt:
                chosen[i]["kind"] = alt
    night = _night_session(ctx)
    shots = [_make_shot(C, track, o, n, night) for n, o in enumerate(chosen, 1)]
    plan = {"project": slug, "replay": rpath, "replay_kind": rkind, "sync": sync,
            "timeline": "output" if ctx.spans is not None else "source",
            "settings": {k: C[k] for k in DEFAULTS if k in C} | {"allowed_kinds": C["allowed_kinds"]},
            "notes": notes, "skipped": skipped, "shots": shots}
    if write:
        _write(shots_path(slug), plan)
    return plan


