def busy_output_intervals(edl: dict, spans, pad: float = 0.0) -> list[tuple[float, float, str]]:
    """Output-time intervals a cinematic shot must not sit on: meme cutaways / cards, green screens, video clips,
    image stickers, sticker_pop motion graphics (other cinematic overlays are ignored)."""
    from .edl import resolve_time
    out = []
    for sp in spans:
        if sp.src_in is None:
            out.append((sp.out_start - pad, sp.out_end + pad, f"{edl['segments'][sp.seg_index].get('type')} segment"))
    for ev in edl.get("overlays", []):
        if ev.get("cinematic"):
            continue
        typ = ev.get("type")
        if typ not in ("greenscreen", "video", "image") and ev.get("template") != "sticker_pop":
            continue
        at = resolve_time(ev, spans, [], "busy")
        if at is None:
            continue
        d = ev.get("dur") or 1.5
        out.append((at - pad, at + d + pad, f"existing {typ if typ != 'motion' else 'sticker'} overlay"))
    return out


