_OBS_RX = re.compile(r"(\d{4})[-_](\d{2})[-_](\d{2})[ T_-](\d{2})[-_:.](\d{2})[-_:.](\d{2})")


def parse_obs_name(name: str) -> datetime | None:
    """'2026-10-06 13-51-50.mp4' (OBS default), '2026-10-10T14_25_31.zip' (Flashback) -> naive local datetime."""
    m = _OBS_RX.search(Path(name).name)
    if not m:
        return None
    try:
        return datetime(*[int(x) for x in m.groups()])
    except ValueError:
        return None


def _probe_duration(path: Path) -> float | None:
    try:
        r = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", str(path)],
                           capture_output=True, text=True, timeout=60)
        return float(r.stdout.strip())
    except (OSError, ValueError, subprocess.TimeoutExpired):
        return None


def video_window(slug: str) -> dict:
    """Wall-clock window of the project's recording: {start, end, dur, file, how} (epoch seconds, local clock)."""
    pj = _read(PROJECTS / slug / "project.json", {}) or {}
    game = ((pj.get("sources") or {}).get("game") or {}).get("file")
    f = Path(game) if game else None
    dur = float(pj.get("duration_s") or 0) or (_probe_duration(f) if f and f.exists() else 0) or 0.0
    dt = parse_obs_name(f.name) if f else None
    if dt is not None:
        start, how = dt.timestamp(), "OBS filename"
        if f.exists():                      # the filename is whole seconds: the file's end time minus its longest stream
            fdur = _probe_duration(f)       # gives the start to ~0.1 s (real session: 36.92 vs OBS log 36.83)
            if fdur and abs((f.stat().st_mtime - fdur) - start) < 2.0:
                start, how, dur = f.stat().st_mtime - fdur, "OBS filename refined by file end time", fdur or dur
    elif f is not None and f.exists():
        start, how = f.stat().st_mtime - dur, "file mtime minus duration"
    else:
        raise SystemExit(f"{slug}: cannot place the recording in time (no game file / timestamp)")
    return {"start": start, "end": start + dur, "dur": dur, "file": str(f) if f else None, "how": how}


def replay_window(path: Path) -> dict:
    """Wall-clock window of a replay file: {start, end, dur, kind}. Verified against real files:
    Flashback metadata.json `name` is the SAVE time (start = name - total_ticks/20); Replay Mod metaData.json `date`
    is the START (epoch ms) and `duration` is in ms."""
    path = Path(path)
    with zipfile.ZipFile(path) as z:
        names = set(z.namelist())
        if "metadata.json" in names:                                             # Flashback
            m = json.loads(z.read("metadata.json"))
            end_dt = parse_obs_name(str(m.get("name") or "")) or parse_obs_name(path.name)
            if end_dt is None:
                raise ValueError(f"{path.name}: no timestamp in metadata name")
            dur = float(m.get("total_ticks", 0)) / 20.0
            end = end_dt.timestamp()
            return {"start": end - dur, "end": end, "dur": dur, "kind": "flashback", "path": str(path)}
        if "metaData.json" in names:                                              # Replay Mod
            m = json.loads(z.read("metaData.json"))
            start = float(m["date"]) / 1000.0
            dur = float(m.get("duration", 0)) / 1000.0
            return {"start": start, "end": start + dur, "dur": dur, "kind": "replaymod", "path": str(path)}
    raise ValueError(f"{path}: not a Flashback or Replay Mod archive")


def list_replays(dirs: list[Path] | None = None) -> list[dict]:
    out = []
    for d in dirs or [FLASHBACK_DIR, REPLAYMOD_DIR]:
        if not Path(d).is_dir():
            continue
        for f in sorted(Path(d).iterdir()):
            if f.suffix.lower() in (".zip", ".mcpr"):
                try:
                    out.append(replay_window(f))
                except (OSError, ValueError, KeyError, zipfile.BadZipFile):
                    continue
    return out


def overlap_s(a: dict, b: dict) -> float:
    return max(0.0, min(a["end"], b["end"]) - max(a["start"], b["start"]))

def running_minecraft(list_processes=None) -> list[dict]:
    """java/javaw processes whose command line mentions minecraft (the TLauncher game or ours)."""
    procs = (list_processes or _powershell_processes)()
    hits = []
    for p in procs:
        cmd = (p.get("cmd") or "").lower()
        if "minecraft" in cmd:
            hits.append({"pid": p.get("pid"), "name": p.get("name"), "cmd": (p.get("cmd") or "")[:200]})
    return hits


def check_plan(plan: LaunchPlan) -> list[str]:
    """Problems that would stop a launch (missing files)."""
    return list(plan.missing)


# ------------------------------------------------------------------------------------------------ arming
def write_armed(job_file: str | Path, token: str | None = None, now: float | None = None) -> Path:
    """Write ``ARMED`` next to the job file. The mod needs this AND -Dflashback_auto.job (and matching token) to do anything."""
    job_file = Path(job_file).resolve()
    p = job_file.with_name(ARMED)
    body = {"job": str(job_file), "created": int(now if now is not None else time.time()), "pid": os.getpid()}
    if token:
        body["token"] = token
    p.write_text(json.dumps(body), encoding="utf-8")
    return p


def disarm(job_file: str | Path) -> None:
    try:
        Path(job_file).resolve().with_name(ARMED).unlink()
    except FileNotFoundError:
        pass


# ------------------------------------------------------------------------------------------------ launching
class GameProcess:
    """Thin wrapper over the Popen handle (also what tests replace with a fake)."""

    def __init__(self, popen: subprocess.Popen):
        self._p = popen
        self.pid = popen.pid

    def poll(self):
        return self._p.poll()

    def wait(self, timeout=None):
        return self._p.wait(timeout)

    def kill_tree(self) -> None:
        if self._p.poll() is None:
            subprocess.run(["taskkill", "/PID", str(self.pid), "/T", "/F"], capture_output=True, creationflags=CREATE_NO_WINDOW)
            try:
                self._p.wait(15)
            except subprocess.TimeoutExpired:
                self._p.kill()


def launch(plan: LaunchPlan, log_path: str | Path | None = None, *, list_processes=None, popen=subprocess.Popen) -> GameProcess:
    """Start the game. Refuses on missing files or when another Minecraft is running."""
    probs = check_plan(plan)
    if probs:
        raise LaunchError("cannot launch, missing:\n  " + "\n  ".join(probs))
    other = running_minecraft(list_processes)
    if other:
        raise LaunchError("another Minecraft is already running, not launching: "
                          + "; ".join(f"pid {o['pid']} {o['name']}" for o in other))
    if plan.natives_dir and not plan.natives_dir.exists():
        plan.natives_dir.mkdir(parents=True, exist_ok=True)
    out = open(log_path, "ab") if log_path else subprocess.DEVNULL
    try:
        p = popen(plan.command, cwd=str(plan.cwd), stdin=subprocess.DEVNULL, stdout=out, stderr=subprocess.STDOUT,
                  creationflags=CREATE_NO_WINDOW | BELOW_NORMAL_PRIORITY_CLASS | CREATE_NEW_PROCESS_GROUP)
    finally:
        if log_path:
            out.close()
    return GameProcess(p)


